INSERT INTO `product` VALUES (13,'Robot Chú Chó Tinh Nghịch VECTO VT18012','f2a4e5f330de44c8fbf6ed4650e03933',649000,1204,0,6,'Đồ Chơi VECTO Robot Chú Chó Tinh Nghịch - Nô Đùa Cùng Bé VT18012<br><br>Dễ thương và lém lỉnh, tinh nghịch nhưng đầy tháo vát. Robot chú chó tinh nghịch đã đến rồi đây. Các bé và ba mẹ đã sẵn sàng rước chú về chưa nè?<br><br>- Khả năng sủa giống hệt chó thật<br><br>- Nhảy múa theo nhạc cực Cool<br><br>- Chức năng lập trình một chuỗi động tác độc đáo<br><br>- Điều khiển linh hoạt tới, lui, trái , phải<br><br>Ngoài các chức năng nổi trội trên với thiết kế vẻ mặt cực kỳ dễ thương nhưng không kém phần nghịch ngợm sẽ giúp cho các giây phút vui chơi của bé vô cùng hào hứng.<br><br>Bộ sản phẩm bao Robot chú chó tinh nghịch gồm:<br><br>1 x Robot chú chó tinh nghịch (có kèm pin sạc bên trong)<br><br>1 x Remote điều khiển (xài pin tiểu Không kèm pin)<br><br>1 x Cáp sạc USB<br><br>VECTO - THẾ GIỚI ĐỒ CHƠI BÉ TRAI CỰC ĐỈNH<br><br>VECTO là thương hiệu đồ chơi dành riêng cho các bé trai, với các dòng đồ chơi trải dài từ đồ chơi điều khiển từ xa cho đến các dòng đồ chơi lắp ráp. Với mong muốn giúp các bé trai có một sự phát triển toàn diện từ trí não đến thể chất, Vecto đã phát triển đa dạng các loại đồ chơi để đem đến cho bé nhiều lựa chọn nhất có thể, có thể kể đến như:<br><br>- ROBOT ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY SÁNG TẠO<br><br>- XE ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY PHƯƠNG HƯỚNG<br><br>- ĐỒ CHƠI BAY – PHÁT TRIỂN TƯ DUY LOGIC<br><br>- ĐỒ CHƠI LẮP RÁP DIY – PHÁT TRIỂN KỸ NĂNG VẬN ĐỘNG TINH<br><br>Và còn nhiều dòng đồ chơi khác đang đợi bé khám phá',0,1194,10),(14,'Robot Mèo Con Thông Thái VECTO VT2059','19f7c9c38c2d6019543ced0b743fdb1d',599000,1200,0,6,'Đồ Chơi VECTO Robot Mèo Con Thông Thái Học Tập Cùng Bé VT2059<br><br>Đáng yêu và nhí nhảnh, nghịch ngợm và thông thái. Robot mèo con thông thái đã đến rồi đây. Ba mẹ đã sẵn sàng rước chú về học tập vui chơi với bé nhà mình chưa?<br><br> - Đố vui các câu hỏi thường thức hay các câu hỏi toán học cùng bé (các câu hỏi sẽ được hỏi bằng tiếng anh – Bé có thể chọn đáp án đúng bằng cách nhấn A,B,C ở trên Remote)<br><br> - Hệ thống lập trình chuỗi hành động độc đáo.<br><br> - Điều khiển linh hoạt tới, lui, trái , phải<br><br> - Chức năng tự động trình diễn<br><br>Vẻ ngoài của chú robot mèo con thông thái là sự kết hợp hài hòa giữa hai màu sắc đen và vàng, tạo nên một vẻ ngoại trang bắt mắt và vô cùng đặc biệt.<br><br>Còn chần chờ gì nữa mà ba mẹ không rước ngay một chú mèo cực kỳ thông minh về nhà để bầu bạn cùng bé.<br><br>*Bộ câu hỏi và câu trả lời (tiếng anh) có tích hợp trong sách Hướng dẫn sử dụng đi kèm.<br><br>Bộ sản phẩm Robot mèo con thông thái bao gồm:<br><br>1 x Mèo con thông thái (xài pin tiểu, không kèm pin)<br><br>1 x Remote điều khiển (xài pin tiểu, không kèm pin)<br><br>1 x sách hướng dẫn câu hỏi/ cách chơi<br><br>VECTO - THẾ GIỚI ĐỒ CHƠI BÉ TRAI CỰC ĐỈNH<br><br>VECTO là thương hiệu đồ chơi dành riêng cho các bé trai, với các dòng đồ chơi trải dài từ đồ chơi điều khiển từ xa cho đến các dòng đồ chơi lắp ráp. Với mong muốn giúp các bé trai có một sự phát triển toàn diện từ trí não đến thể chất, Vecto đã phát triển đa dạng các loại đồ chơi để đem đến cho bé nhiều lựa chọn nhất có thể, có thể kể đến như:<br><br>- ROBOT ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY SÁNG TẠO<br><br>- XE ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY PHƯƠNG HƯỚNG<br><br>- ĐỒ CHƠI BAY – PHÁT TRIỂN TƯ DUY LOGIC<br><br>- ĐỒ CHƠI LẮP RÁP DIY – PHÁT TRIỂN KỸ NĂNG VẬN ĐỘNG TINH<br><br>Và còn nhiều dòng đồ chơi khác đang đợi bé khám phá<br><br>',0,1192,0),(15,'Đồ Chơi Robot Patrol Man Điều Khiển Từ Xa VECTO VTK46','03b4e434a1665643e7205c77345b1412',799000,3000,4,6,'Đồ Chơi Robot Patrol Man Điều Khiển Từ Xa VECTO VTK46<br>Đồ chơi Robot Patrol Man điều khiển từ xa VECTO – Người máy tiên tiến đa chức năng cho bé vừa học vừa chơi, khám phá thế giới công nghệ tương lai cực vui:<br>+ Chế độ lập trình trí tuệ: nhấn nút “lập trình” và thiết lập các động tác mong muốn, sau đó nhấn “lập trình” một lần nữa, robot sẽ thực hiện chính xác theo những động tác vừa được cài đặt<br>+ Phần đầu robot có thể xoay trái phải linh hoạt<br>+ Chế độ cảm biến theo cử chỉ tay: bật chế độ cảm biến, để tay lại gần robot và di chuyển tiến lùi trái phải – robot sẽ di chuyển tiến lùi trái phải theo cử chỉ tay<br>+ Khả năng tương tác khi chạm: chạm vào phần đầu và robot sẽ nhảy theo nhạc<br>+ Chế độ tự động trình diễn<br>+ Di chuyển tiến lùi, rẽ trái, rẽ phải theo cả 2 chế độ: bước đi, trượt<br>+ Có đèn<br>+ Sử dụng pin sạc, cáp sạc USB đi kèm<br><br>THÔNG TIN VỀ SẢN PHẨM:<br>Kích thước hộp hàng: 26.6 x 14.6 x 30.5 cm<br>Chủ đề: VECTO ROBOT<br>Năm sản xuất: 2024<br>Xuất xứ thương hiệu: Việt Nam<br>Chất liệu: Nhựa và kim loại (An toàn tuyệt đối với bé)<br><br>Bộ đồ chơi gồm:<br>1 x Robot Patrol Man (Sử dụng pin sạc, có kèm pin)<br>1 x Remote điều khiển từ xa (Sử dụng pin tiểu, không kèm pin)<br>1 x Cáp sạc USB<br>1 x Hướng dẫn sử dụng<br><br>VECTO - THẾ GIỚI ĐỒ CHƠI BÉ TRAI CỰC ĐỈNH<br>VECTO là thương hiệu đồ chơi dành riêng cho các bé trai, với các dòng đồ chơi trải dài từ điều khiển từ xa đến lắp ráp. Với mong muốn giúp các bé trai có sự phát triển toàn diện từ trí não đến thể chất, Vecto đã phát triển đa dạng các loại đồ chơi nhằm mang đến cho bé nhiều lựa chọn nhất có thể, một số dòng đồ chơi nổi bật:<br>- ROBOT ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY SÁNG TẠO<br>- XE ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY PHƯƠNG HƯỚNG<br>- ĐỒ CHƠI BAY – PHÁT TRIỂN TƯ DUY LOGIC<br>- ĐỒ CHƠI LẮP RÁP DIY – PHÁT TRIỂN KỸ NĂNG VẬN ĐỘNG TINH<br>Và còn nhiều dòng đồ chơi khác từ VECTO đang đợi bé khám phá.',0,2994,0),(16,'Đồ Chơi Lắp Ráp Chiến Giáp Của Cole LEGO NINJAGO 71806','406fdc0426987e82926c41bfca22903d',599000,2500,4,2,'Đồ Chơi Lắp Ráp Chiến Giáp Của Cole LEGO NINJAGO 71806 (235 Chi Tiết)<br><br>Siêu chiến giáp của Cole có buồng lái và được trang bị một cây búa để chiến đấu với những tên Chiến binh Sói gian ác. Và bây giờ, bạn có thể kết hợp các bộ phận của 3 cỗ máy ninja tuyệt vời do Cole, Sora và Kai điều khiển để tạo ra cỗ máy kết hợp của riêng bạn. Mỗi cỗ máy có thể tùy chỉnh và được bán riêng, đi kèm với chân, tay, vũ khí và thân có thể tháo rời để bạn có thể kết hợp.<br><br>• Xây dựng những bộ chiến giáp của riêng bạn – Những bé hâm mộ NINJAGO® có thể tận hưởng hàng giờ vui vẻ sáng tạo khi kết hợp các bộ phận từ những bộ đồ chơi khác nhau (được bán riêng) để tạo ra những bộ siêu chiến giáp NINJAGO® của riêng mình<br><br>• 2 nhân vật NINJAGO® – Bộ trò chơi bao gồm Cole với phụ kiện thanh kiếm mini và Chiến binh Sói gian ác cũng có thanh kiếm. Bé có thể tái hiện các trận chiến từ phần 2 của bộ phim hoạt hình NINJAGO Dragons Rising<br><br>• Chiến giáp có thể điều chỉnh được – chiến giáp hạng nặng này có buồng lái để bé có thể đặt Cole vào, một chiếc búa lớn và tay chân có thể điều chỉnh được, có thể nghiêng và điều chỉnh thành các tư thế chiến đấu. Ngoài ra bé có thể hoán đổi và kết hợp các bộ phận từ chiến giáp của Cole với chiến giáp công nghệ của Sora (71807) và chiến giáp Kai (71808) được bán riêng<br><br>• Quà tặng siêu hấp dẫn cho bé – Bộ LEGO® NINJAGO siêu đỉnh này sẽ mang đến cho bé nghiệm lắp ráp và vui chơi sáng tạo. Qúa thích hợp làm quà tặng cho những dịp sinh nhật hoặc lễ Tết.<br><br>• Xây dựng thế giới LEGO® NINJAGO® của bé – Cùng sưu tập thêm những bộ trò chơi LEGO® NINJAGO® khác và xây dựng một thế giới của riêng bé, từ đó mở ra những câu chuyện mới<br><br>• Kích thước – Bộ lắp ráp LEGO® gồm 235 mảnh, sau khi hoàn thiện cao trên 5,5 inch (14 cm)',0,2497,30),(17,'Đồ Chơi Lắp Ráp Tàu Con Thoi Vũ Trụ LEGO CREATOR 31134','0fe5bfd7b7d9c5aa518b1fe7309d7ff5',216000,3600,4,2,'Đồ Chơi Lắp Ráp LEGO Tàu Con Thoi Vũ Trụ 31134 (144 Chi Tiết)<br><br>Tận hưởng những cuộc phiêu lưu kỳ thú giữa các thiên hà với 3 đồ chơi không gian LEGO® khác nhau trong 1 bộ trò chơi. Phóng lên quỹ đạo bằng Tàu con thoi và vệ tinh có thể mở rộng. Sau đó, xây dựng lại nó thành một phi hành gia với tay và chân có thể cử động được – sẵn sàng chinh phục các hành tinh – hoặc xây dựng lại nó thành một con tàu vũ trụ siêu ngầu với đôi cánh đang di chuyển. Việc du hành giữa các vì sao vô tận là chuyện nhỏ với bộ đồ chơi 3 trong 1 tuyệt vời này.<br><br>• Đồ chơi 3 trong 1 – Những người hâm mộ trò chơi ngoài không gian có thể tận hưởng chuyến du hành giữa các thiên hà với bộ đồ chơi LEGO® Creator Tàu Con Thoi Vũ Trụ 3 trong 1 (31134), bao gồm Tàu con thoi, phi hành gia và tàu vũ trụ<br><br>• Vô số tùy chọn chơi – bé yêu có thể chọn chơi hành động với đồ chơi Tàu con thoi, hình đồ chơi phi hành gia với tay và chân có thể điều chỉnh được và tàu vũ trụ siêu ngầu<br><br>• Được đóng gói với các phụ kiện – Tàu con thoi có một cửa sập mở chứa một vệ tinh có thể tháo rời và nhân vật phi hành gia có một bộ phản lực và một lá cờ để cắm trên giá đỡ',0,3596,0),(18,'Xe Scooter 3 Bánh Royal Baby RO203M-3 Xanh Đen','5727731e57a2dc166cab2d6d4811d659',1259000,7000,4,3,'Xe Trượt Xanh Đen Có Điều Chỉnh Độ Cao ROYAL BABY RO203M-3/GR-BK<br><br>Xe scooter 3 bánh Royal Baby RO203M-3 xanh đen cho bé từ 4-8 tuổi là sản phẩm bán chạy nhất trong dòng sản phẩm scooter.<br>RoyalBaby là thương hiệu chuyên sản xuất xe đạp trẻ em được yêu thích nhất tại Bắc Âu và bán chạy nhiều năm liền trên Amazon. Nhờ tập trung vào mảng xe đạp trẻ em, xe scooter trẻ em, các sản phẩm của RoyalBaby được nghiên cứu và thiết kế để đảm bảo đạt chuẩn an toàn, tiện lợi và thoải mái nhất cho bé khi sử dụng.<br><br>Khi chơi scooter, bé được học và cải thiện rất nhiều kỹ năng cần thiết như: Phát triển vận động thô, các cơ lớn như tay, chân; phát triển khả năng phản xạ và sự kết hợp tay, mắt. Ngoài ra, tham gia các hoạt động ngoài trời còn giúp bé học được kỹ năng giao tiếp, kỹ năng xã hội,...<br><br>Đặc điểm nổi bật của sản phẩm:<br><br>Xe scooter Royal Baby RO203M-3/GR-BK có thể điều chỉnh độ cao là sản phẩm có thiết kế cơ chế lái trụ độc đáo, bàn để chân rộng và đặc biệt có thể điều chỉnh độ cao tay lái khác nhau để phù hợp với độ tuổi của bé.<br><br>- Với loại xe này, bé chỉ cần đặt một chân lên mặt xe và dùng chân còn lại đẩy cùng với điều khiển tay lái xe là có thể di chuyển đến các địa điểm yêu thích.<br><br>- Sản phẩm có kiểu dáng nhỏ gọn dễ gấp gọn, dễ di chuyển, cất giữ giúp bé có thể chơi bất cứ nơi đâu.<br><br>- Sản phẩm phù hợp cho cả bé trai và bé gái, có 2 màu cho bé lựa chọn, giúp bé:<br><br>1. Rèn luyện sức khỏe, tập phản xạ và điều khiển đồ vật<br>2. Giúp bé năng động hơn và tăng khả năng tự luyện tập<br>3. Giúp bé luôn tự tin và phát triển thể chất, tinh thần một cách lành mạnh',0,6993,0),(19,'Xe Scooter 2 Bánh Neon Vector Yvolution NT05B2 Xanh Dương','1ccc289bbbc232f5b424de17b75ab944',1599000,5500,3,3,'Scooter thương hiệu NEON với đèn LED phát sáng, chuyến đi chơi của bé vui lại càng vui.<br><br>Đặc điểm nổi bật của sản phẩm:<br><br>1. Phù hợp với bé từ 5 tuổi trở lên.<br> <br>2. Bánh xe gắn đèn LED phát sáng bắt mắt: Đèn sáng nhờ động năng, sáng ngay khi bắt đầu di chuyển, không cần thêm pin. Càng chạy nhanh đèn càng sáng.<br> <br>3. Thiết kế chú trọng an toàn cho bé.<br> <br>4. Tay cầm có gờ chống trơn trượt.<br> <br>5. Phanh sau rộng và nhạy, giúp bé phanh kịp thời, giảm thiểu tai nạn.<br> <br>6. Thiết kế gọn gàng, đẹp mắt.<br> <br>7. Gọn nhẹ, giúp bé dễ di chuyển.<br> <br>8. Dễ điều chỉnh để phù hợp với từng bé, hoặc khi bé phát triển chiều cao.<br> <br>9. Có thể gấp gọn và tháo rời được tay cầm, tiết kiệm diện tích và dễ di chuyển.<br> <br>10. Đèn LED có ba màu để lựa chọn, phù hợp với sở thích và tính cách của từng bé.',0,5497,0),(20,'Xe Scooter 2 Bánh Neon Vector Yvolution NT05P2 Hồng','37b6f4d734f46ed0f59254ea8d117ee2',1599000,4500,3,3,'Scooter thương hiệu NEON với đèn LED phát sáng, chuyến đi chơi của bé vui lại càng vui.<br><br>Đặc điểm nổi bật của sản phẩm:<br><br>1. Phù hợp với bé từ 5 tuổi trở lên.<br>2. Bánh xe gắn đèn LED phát sáng bắt mắt: Đèn sáng nhờ động năng, sáng ngay 3. khi bắt đầu di chuyển, không cần thêm pin. Càng chạy nhanh đèn càng sáng.<br>4. Thiết kế chú trọng an toàn cho bé.<br>5. Tay cầm có gờ chống trơn trượt.<br>6. Phanh sau rộng và nhạy, giúp bé phanh kịp thời, giảm thiểu tai nạn.<br>7. Thiết kế gọn gàng, đẹp mắt.<br>8. Gọn nhẹ, giúp bé dễ di chuyển.<br>9. Dễ điều chỉnh để phù hợp với từng bé, hoặc khi bé phát triển chiều cao.<br>10. Có thể gấp gọn và tháo rời được tay cầm, tiết kiệm diện tích và dễ di chuyển.<br>Đèn LED có ba màu để lựa chọn, phù hợp với sở thích và tính cách của từng bé.',0,4500,0),(21,'Xe Scooter 3 Bánh Royal Baby RO203M-3 Tím Trắng','40b69295a3b1724377bf2250900fa1b4',1259000,7800,3,3,'Đồ Chơi SCOOTER Xe Trxe Scooter 3 Bánh Royal Baby Ro203M-3 Tím Trắng RO203M-3/PU-WH<br><br>Xe scooter 3 bánh Royal Baby RO203M-3 tím trắng cho bé từ 4-8 tuổi là sản phẩm bán chạy nhất trong dòng sản phẩm scooter.<br>RoyalBaby là thương hiệu chuyên sản xuất xe đạp trẻ em được yêu thích nhất tại Bắc Âu và bán chạy nhiều năm liền trên Amazon. Nhờ tập trung vào mảng xe đạp trẻ em, xe scooter trẻ em, các sản phẩm của RoyalBaby được nghiên cứu và thiết kế để đảm bảo đạt chuẩn an toàn, tiện lợi và thoải mái nhất cho bé khi sử dụng.<br><br>Khi chơi scooter, bé được học và cải thiện rất nhiều kỹ năng cần thiết như: Phát triển vận động thô, các cơ lớn như tay, chân; phát triển khả năng phản xạ và sự kết hợp tay, mắt. Ngoài ra, tham gia các hoạt động ngoài trời còn giúp bé học được kỹ năng giao tiếp, kỹ năng xã hội,...<br><br>Đặc điểm nổi bật của sản phẩm:<br><br>Xe scooter Royal Baby RO203M-3/GR-BK có thể điều chỉnh độ cao là sản phẩm có thiết kế cơ chế lái trụ độc đáo, bàn để chân rộng và đặc biệt có thể điều chỉnh độ cao tay lái khác nhau để phù hợp với độ tuổi của bé.<br><br>- Với loại xe này, bé chỉ cần đặt một chân lên mặt xe và dùng chân còn lại đẩy cùng với điều khiển tay lái xe là có thể di chuyển đến các địa điểm yêu thích.<br><br>- Sản phẩm có kiểu dáng nhỏ gọn dễ gấp gọn, dễ di chuyển, cất giữ giúp bé có thể chơi bất cứ nơi đâu.<br><br>- Sản phẩm phù hợp cho cả bé trai và bé gái, có 2 màu cho bé lựa chọn, giúp bé:<br><br>+ Rèn luyện sức khỏe, tập phản xạ và điều khiển đồ vật<br><br>+ Giúp bé năng động hơn và tăng khả năng tự luyện tập<br><br>+ Giúp bé luôn tự tin và phát triển thể chất, tinh thần một cách lành mạnh',0,7799,10),(22,'Xe Đạp Trẻ Em Royal Baby Little Swan 12 Inch Hồng RB12-18','d70a87c5ed96b4a8559c447795fb8fd7',2899000,6600,2,4,'- Little Swan là dòng xe đáng yêu dành cho bé gái, thuộc thương hiệu RoyalBaby được yêu thích tại Bắc Âu, thiết kế sản phẩm và màu sắc phù hợp với cơ thể của bé yêu, cùng độ an toàn cao sẽ là lựa chọn tuyệt vời của bố mẹ dành cho bé thỏa sức vui chơi vận động mỗi ngày.<br><br>- Sản phẩm được nhập khẩu và phân phối chính hãng bởi MYKINGDOM, với thời hạn bảo hành lên đến 5 năm.<br><br>Điểm Nổi Bật Của Sản Phẩm:<br><br>+ LỐP CAO SU khí nén rộng 5.5cm<br>+ PHANH TAY được thiết kế phù hợp với kích thước bàn tay & lực bóp của bé<br>+ BÀN ĐẠP chống trượt<br>+ TAY CẦM cao su chống trượt đạt tiêu chuẩn EU<br>+ YÊN XE bằng foam vinyl êm ái, có thanh đỡ phía sau.<br>+ GIỎ XE ĐẠP thiết kế màu hồng đáng yêu, tiện lợi cho bé để dụng cụ cá nhân.',0,6600,0),(23,'Xe Đạp Trẻ Em Royal Baby Flying Bear 16 Inch Màu Vàng RB16B-9','3e17ecc390ec33820b649d04b317d4a0',3475000,9000,3,4,'Xe Đạp Trẻ Em, RoyalBaby Flying Bear 16\", Màu Vàng, Bé Từ 5-9 Tuổi RB16B-9/YELLOW <br><br>RoyalBaby là thương hiệu xe đạp trẻ em được yêu thích nhất khu vực Bắc Âu và bán chạy trên Amazon trong nhiều năm liền. Khung xe làm bằng thép cường lực, lắp ráp bằng robot, tải trọng 2 người lớn đảm bảo an toàn tuyệt đối cho bé. <br><br>Mô Tả Sản Phẩm: <br> - Flying Bear là dòng xe cho bé, với thiết kế mạnh mẽ như một chu gấu rừng đáng yêu, thuộc thương hiệu RoyalBaby được yêu thích tại Bắc Âu, thiết kế sản phẩm và màu sắc phù hợp với cơ thể của bé yêu, cùng độ an toàn cao sẽ là lựa chọn tuyệt vời của bố mẹ dành cho bé thỏa sức vui chơi vận động mỗi ngày.<br><br>- Sản phẩm được nhập khẩu và phân phối chính hãng bởi MYKINGDOM, với thời hạn bảo hành lên đến 5 năm.<br><br>Điểm Nổi Bật Của Sản Phẩm:<br>+ KHUNG THÉP được hàn TIG<br>+ LỐP CAO SU khí nén rộng 6cm<br>+ HỘP XÍCH bằng nhựa ABS siêu bền<br>+ PHANH TAY được thiết kế phù hợp với kích thước bàn tay & lực bóp của bé<br>+ BÀN ĐẠP chống trượt<br>+ TAY CẦM cao su chống trượt đạt tiêu chuẩn EU<br>+ YÊN XE bằng foam vinyl êm ái, có thanh đỡ phía sau.',0,8999,0),(24,'Xe Điều Khiển 1:24 Ferrari FXXK Evo RASTAR R79300','04a6a0257f3c2cdaa908056b2e525c6e',479000,12000,3,5,'Đồ Chơi Xe Điều Khiển Ferrari FXXK Evo Tỷ Lệ 1:24 RASTAR R79300<br><br>Xe điều khiển Ferrari FXXK Evo R79300 của thương hiệu RASTAR, được mua bản quyền và mô phỏng lại chính xác với tỷ lệ thu nhỏ 1:24. Sở hữu thiết kế chân thực như một chiếc xe ngoài đời thật, sản phẩm không chỉ là món đồ chơi giải trí sau những giờ học tập mệt mỏi mà còn giúp bé có thêm kiến thức về các loại phương tiện giao thông.<br><br>Siêu xe điều khiển RASTAR R79300 với các chức năng mạnh mẽ, hình dáng lôi cuốn, là một người bạn tuyệt vời không thể thiếu trong bộ sưu tập “xế hộp” của bé. Sản phẩm có các đặc điểm nổi bật sau:<br><br>1. Mô hình xe điều khiển được sản xuất theo quy trình chất lượng cao, tuân thủ các tiêu chuẩn nghiêm ngặt của châu Âu, hoàn toàn không chứa chất gây hại. <br><br>2. Xe có màu sắc nổi bật, hình dáng sang trọng, mạnh mẽ, giúp kích thích thị giác của bé.<br><br>3. Thiết kế an toàn, không góc cạnh, không làm trầy xước da bé.<br><br>4. Xe có thể tiến, lùi, rẽ trái, rẽ phải dễ dàng bằng điều khiển từ xa, tự tay điều khiển chiếc xe mình yêu thích sẽ làm cho các bạn nhỏ vô cùng thích thú.<br><br>5. Lốp xe làm bằng cao su nguyên chất, an toàn và có độ bám tốt trên sàn.<br><br>6. Xe và điều khiển sử dụng pin 2A dễ dàng thay và có thời gian sử dụng lâu.<br><br>Bộ đồ chơi xe điều khiển Ferrari FXXK Evo tỷ lệ 1:24 RASTAR R79300 bao gồm:<br><br>- 01 mô hình xe.<br>- 01 điều khiển từ xa.<br>- Vài nét về thương hiệu đồ chơi:<br><br>RASTAR đến từ Trung Quốc, là thương hiệu nổi tiếng về sản xuất mô hình xe điều khiển, với hơn 20 năm kinh nghiệm trong việc thỏa mãn niềm đam mê siêu xe của các bé. Các sản phẩm RASTAR được làm từ chất liệu cao cấp, kiểu dáng được thiết kế chuyên nghiệp giống hệt các mẫu xe thật được đưa ra và ứng dụng công nghệ sơn hiện đại, sử dụng robot ABB tiên tiến để phun sơn đảm bảo đúng yêu cầu về màu sắc và chi tiết tinh xảo từ các hãng xe khó tính nhất.',1,11997,0),(25,'Xe Điều Khiển BMW I8 Bạc RASTAR R48400-2','0125dadc0dac9879659860de41ea00e7',479000,15000,3,5,'Xe Điều Khiển BMW I8 Bạc RASTAR R48400-2<br><br>Xe điều khiển BMW i8 Bạc RASTAR R48400-2 là sản phẩm đồ chơi được thiết kế theo tỉ lệ 1:24, nhỏ hơn 24 lần so với thực tế. Tuy nhiên các chi tiết đều đầy đủ từ nội thất cho đến bên ngoài, mang lại cảm giác như thật cho người chơi.<br><br><br>Mô hình có trục bánh xe trước, có thể xoay tròn 360 độ, bé có thể điều khiển xe một cách mượt mà đầy ấn tượng. Bé dễ dàng điều khiển thông qua tay cầm một cách dễ dàng, xe tiến lùi, sang trái sang phải tùy ý thích của bé. Từ đó, sản phẩm giúp bé rèn luyện khả năng khéo léo của đôi bàn tay.<br><br>Xe điều khiển BMW i8 Bạc được yêu thích bởi những đặc điểm nổi bật sau:<br><br><br>1. Kích thước bao bì: 38.5x12x10 cm, trọng lượng 300 gram, gọn nhẹ. Thích hợp cho bé mang theo đến bất cứ đâu.<br><br>2. Màu sắc bóng loáng, kiểu dáng hiện đại và cá tính giúp bé có những giờ phút thư giãn cùng người thân và bạn bè mỗi ngày.<br><br>3. Chất liệu sử dụng là nhựa và kim loại cao cấp, không chứa chất độc hại, an toàn và thân thiện cho mọi lứa tuổi.<br><br>4. Xe và bộ sạc có dùng pin. Không kèm theo mô hình.<br><br>5. Sản phẩm được khuyên dành cho các bé trai trên 6 tuổi.<br><br>Xe điều khiển với thiết kế sang trọng, lịch lãm đầy mạnh mẽ sẽ là món quà mà con yêu của bạn yêu thích nhất. Nhanh tay đặt hàng để sở hữu siêu xe điều khiển nhé!<br><br>Đồ chơi Xe điều khiển BMW i8 Bạc RASTAR R48400-2 gồm:<br><br>01 xe BMW i8 Bạc và tay cầm điều khiển từ xa.<br><br>Vài nét về thương hiệu:<br><br>Tập đoàn Rastar là công ty chuyên sản xuất và phân phối mô hình điều khiển từ xa. Với hơn 20 năm kinh nghiệm, tất cả các sản phẩm của hãng đều đáp ứng được những yêu cầu khắt khe về chất lượng, kiểu dáng giống hệt so với nguyên bản của các dòng xe nổi tiếng trên thế giới như BMW, Lamborghini, Mercedes,… Đến nay, đồ chơi Rastar đã có mặt trên 120 quốc gia và vùng lãnh thổ. Trở thành một trong những món đồ chơi yêu thích nhất của trẻ em.',1,14998,10),(26,'Xe Điều Khiển 1:24 Lamborghini Aventador SVJ Màu Vàng RASTAR R96100','4fc95901416c608291e6ddfa6f63d6c6',479000,11000,3,5,'Đồ Chơi RASTAR Xe Điều Khiển 1:24 Lamborghini Aventador Svj Màu Vàng R96100/YEL<br>1. Xe đồ chơi điều khiển Rastar được mua bản quyền sử dụng từ chính hãng xe Lamborghini danh tiếng thế giới<br>2. Là phiên bản thu nhỏ tỉ lệ 1:24 từ siêu xe Lamborghini Aventador SVJ với các đường nét và chi tiết sắc sảo nhất<br>3. Được sản xuất với công nghệ tiên tiến dưới sự giám sát của đội ngũ kỹ thuật viên từ chính hãng xe Lamborghini cử đến<br>4. Tay cầm điều khiển vừa tay, dễ thao tác<br>5. Chức năng: tiến, lùi, trái, phải. Cảm nhận độ chạy êm mượt của 1 con xe điều khiển có chất lượng<br>6. Đồ chơi điều khiển bảo đảm an toàn cho trẻ hoặc là món quà tuyệt vời với bao bì sang trọng<br>7. Hàng chính hãng có phiếu bảo hành 30 ngày<br><br>Vài nét về thương hiệu RASTAR:<br>RASTAR đến từ Trung Quốc, là thương hiệu nổi tiếng về sản xuất mô hình xe điều khiển, với hơn 20 năm kinh nghiệm trong việc thỏa mãn niềm đam mê siêu xe của các bé. Các sản phẩm RASTAR được làm từ chất liệu cao cấp, kiểu dáng được thiết kế chuyên nghiệp giống hệt các mẫu xe thật được đưa ra và ứng dụng công nghệ sơn hiện đại, sử dụng robot ABB tiên tiến để phun sơn đảm bảo đúng yêu cầu về màu sắc và chi tiết tinh xảo từ các hãng xe khó tính nhất.',1,10997,0),(27,'Siêu Xe Biến Hình Điều Khiển Từ Xa (Xanh Lá) VECTO VT602','6997bb6882afdef6333d9a6cf9cca1ab',649000,9900,3,5,'Đồ Chơi VECTO Siêu Xe Biến Hình Điều Khiển Từ Xa (Xanh Lá) VT602/GRN<br><br>Ảo diệu và biến ảo khôn lường, thanh thoát và điêu luyện. Bạn đã sẵn sàng chào đón sự xuất hiện của Siêu xe biến hình điều khiển từ xa chưa?<br><br>- Biến ảo khôn lường trong mọi tình huống<br><br>- Xoay vòng 360 độ như cơn lốc xoáy<br> <br>- Nhào lộn và biến hình trong nháy mắt<br> <br>- Hệ thống đèn LED cực đỉnh<br> <br>Với phong cách thiết kế “Nghệ thuật đường phố” siêu xe biến hình mang nét thiết kế đặc trưng phong trần nhưng không kém phần tao nhã.<br><br>Với các đường viền được cắt dứt khoát chạy dọc thân xe tạo nên sự mạnh mẽ trong thiết kế, chưa dừng lại ở đó xe còn được tích hợp thêm 1 bánh giữa để tạo nên sự độc đáo khi vui chơi. Bé sẽ trở thành một nghệ sĩ đường phố tài ba trong lúc trình diễn những màn nhào lộn ấn tượng cùng Deformation Stunt.<br><br>Bộ sản phẩm Siêu xe biến hình điều khiển từ xa bao gồm:<br><br>1 x Xe điều khiển<br><br>1 x Remote điều khiển (xài pin tiểu không kèm pin)<br><br>1 x cáp sạc USB<br><br>1 x Pin sạc<br><br>VECTO - THẾ GIỚI ĐỒ CHƠI BÉ TRAI CỰC ĐỈNH<br><br>VECTO là thương hiệu đồ chơi dành riêng cho các bé trai, với các dòng đồ chơi trải dài từ đồ chơi điều khiển từ xa cho đến các dòng đồ chơi lắp ráp. Với mong muốn giúp các bé trai có một sự phát triển toàn diện từ trí não đến thể chất, Vecto đã phát triển đa dạng các loại đồ chơi để đem đến cho bé nhiều lựa chọn nhất có thể, có thể kể đến như:<br><br>- ROBOT ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY SÁNG TẠO<br><br>- XE ĐIỀU KHIỂN – PHÁT TRIỂN TƯ DUY PHƯƠNG HƯỚNG<br><br>- ĐỒ CHƠI BAY – PHÁT TRIỂN TƯ DUY LOGIC<br><br>- ĐỒ CHƠI LẮP RÁP DIY – PHÁT TRIỂN KỸ NĂNG VẬN ĐỘNG TINH<br><br>Và còn nhiều dòng đồ chơi khác đang đợi bé khám phá',1,9899,0),(28,'Xe Lamborghini Sesto Elemento RASTAR R53700','ded961a20e12c0faa3680a2f39a99000',719000,10000,3,5,'Đồ Chơi RASTAR Xe Lamborghini Sesto Elemento R53700<br>+ Xe Rastar có bản quyền chính hãng thương hiệu xe Lamborghini nổi tiếng thế giới<br>+ Tỷ lệ 1:18 (Mỗi kích thước: Dài Rộng Cao nhỏ hơn 18 lần so với xe thật)<br>+ Mô phỏng tinh xảo, tỉ mỉ từng chi tiết so với xe Lamborghini Sesto Elemento thật<br>+ Xe điều khiển tiến, lùi, rẽ trái, rẽ phải<br>+ Được làm từ nhựa và kim loại cao cấp, đảm bảo cho sự chắc chắn và độ bền của xe<br>+ Bánh xe bằng cao su giúp tăng độ bám với bề mặt, giúp xe chạy đầm và êm hơn<br>+ Bảo hành 30 ngày tại Mykingdom nếu có lỗi từ nhà sản xuất<br>+ Sản phẩm không kèm pin<br><br>Vài nét về thương hiệu RASTAR:<br>RASTAR là thương hiệu nổi tiếng về sản xuất mô hình xe điều khiển, với hơn 20 năm kinh nghiệm trong việc thỏa mãn niềm đam mê siêu xe của các bé. Các sản phẩm RASTAR được làm từ chất liệu cao cấp, kiểu dáng được thiết kế chuyên nghiệp giống hệt các mẫu xe thật, ứng dụng công nghệ sơn hiện đại, sử dụng robot ABB tiên tiến để phun sơn, đảm bảo đúng yêu cầu về màu sắc và chi tiết tinh xảo từ các hãng xe khó tính nhất.',1,9998,0),(30,'Siêu Robot Hộ Thần Mãnh Sư Kim Ngưu Leo Bull V MINIFORCE 503009','a66b311bfc50e92ce4859b91c41b78b3',1129000,6000,2,1,'Đồ Chơi Siêu Robot Hộ Thần Mãnh Sư Kim Ngưu Leo Bull V MINIFORCE 503009<br><br>Siêu Robot Hộ Thần Mãnh Sư Kim Ngưu Leo Bull V là sản phẩm thuộc thương hiệu SAMG Entertainment, một sản phẩm đến từ Series phim hoạt hình được nhiều bạn nhỏ yêu thích – MINIFORCE<br><br>Robot có khả năng biến hình từ Robot sang xe sư tử Leo, bò Bull và ngược lại. Bé thỏa sức sáng tạo với 2 kiểu biến hình này.<br><br>Bộ đồ chơi mô phỏng theo nhân vật Mãnh Sư Kim Ngưu - Hộ thần Leo Bull V từ bộ phim Miniforce V - Biệt đội siêu nhân nhí- phần Chiến binh rừng xanh.<br><br>Thông tin sản phẩm:<br><br>Chứa các chi tiết đều được làm hoàn toàn từ chất liệu nhựa ABS cao cấp, ráp nối với nhau một cách tỉ mỉ, đảm bảo độ chắc chắn cũng như tính mỹ quan của sản phẩm.<br><br>Chất liệu nhựa không bao gồm những thành phần độc hại cho sức khoẻ của trẻ nhỏ khi sử dụng trong thời gian dài.',1,5999,15),(31,'Đồ Chơi Xe Biến Hình Bò Húc Cuồng Hỏa SCREECHERS WILD YW684203','d28232da6b5252446cfb1c78c521336b',239000,7000,3,1,'Chiến xa cổ đại BÒ HÚC CUỒNG HỎA.<br>Ngủ vùi trong nền văn minh cổ đại suốt 200 triệu năm, Bò Húc Cuồng Hỏa chính là chiến binh mang trong mình sứ mệnh bảo vệ hành tinh khỏi sự đe dọa đáng sợ của chiến xa Đế Vương.<br>Sau khi được Wilbur đánh thức, Bò Húc Cuồng Hỏa lại tiếp tục đồng hành cùng nhóm Thợ Săn Tinh Anh để hoàn thành sứ mệnh của mình. <br>Thuộc dòng chiến xa song kích, Bò Húc Cuồng Hỏa khi biến hình sẽ ăn 2 xu và xoay 180 độ.<br>Khi kết hợp 2 chiến xa với nhau có thể ăn được 3 xu.<br>Điểm đặc biệt ở dòng song kích đó là khả năng kết hợp chiến xa không giới hạn, tạo nên một hợp thể sức mạnh bất bại.<br>Hãy sở hữu ngay siêu phẩm đồ chơi cực hot bước ra từ bộ phim THỢ SĂN CHIẾN XA nhé!<br>CÙNG TRỞ THÀNH THỢ SĂN CHIẾN XA DŨNG CẢM VÀ LÊN ĐƯỜNG TRUY TÌM ĐỒNG XU ĐẾ VƯƠNG THÔI NÀO!<br>Sản phẩm đồ chơi xe biến hình Bò Húc Cuồng Hỏa gồm 1 xe biến hình, 1 đồng xu kích hoạt chế độ chiến xa, 1 đồng xu bí mật.',1,7000,0),(32,'Robot Biến Hình Xe Cảnh Sát Poli ROBOCAR POLI MRT0650','9318e56a024cbf9b6b711683b3488dd8',289000,8000,2,1,'Đồ Chơi ROBOCAR POLI Robot Biến Hình Xe Cảnh Sát Poli MRT0650<br>POLI - nhân vật cảnh sát, vô cùng mạnh mẽ và không dễ dàng bỏ cuộc. Cậu ấy trung thực, có trách nhiệm cao trong việc giữ an toàn cho thị trấn và bảo vệ tính mạng cũng như tài sản của cư dân. Poli - người thủ lĩnh tốc độ & đáng tin cậy.<br><br>- Bộ đồ chơi biến hình từ xe cảnh sát thành robot và ngược lại chỉ trong 4 bước chơi.<br><br>- Xe cảnh sát chạy siêu mượt<br><br>- Chất liệu mô hình cứng cáp, an toàn, không gây hại sức khỏe.<br><br>- Kích thước to lớn, dễ dàng quan sát: 11 x 11 x 15.5 cm<br><br>- Sản phẩm không chỉ là món đồ chơi giải trí mà còn giúp bé thực hành kỹ năng giải quyết vấn đề, phát triển vận động tinh, giúp phối hợp tay và mắt; đặc biệt phát huy sự sáng tạo của chính mình khi hóa thân vào nhân vật mà các bé yêu thích.',0,7998,20),(33,'Mô Hình Siêu Anh Hùng Spiderman 30cm SPIDERMAN E7333','e00dbe24880f6041d35383ca9f42f8f5',559000,10000,2,1,'Đồ Chơi Mô Hình Siêu Anh Hùng Spiderman 30cm E7333<br>Mô hình siêu anh hùng Spiderman E7333 sở hữu kích thước to lớn - 30cm cùng hình dáng mạnh mẽ, chân thực, là món đồ chơi mô hình mà các bé dù ở độ tuổi nào cũng vô cùng thích thú. Với đồ chơi siêu anh hùng người nhện các bé sẽ có những giây phút vui chơi và học tập đầy thú vị.<br><br>Nhân vật người nhện thường được coi là một anh hùng chính nghĩa quả cảm với lý tưởng kiên định về công lý và trách nhiệm. Với những tình huống hóm hỉnh mà anh đã trải qua, Spiderman trở thành một trong những nhân vật mẫu mực nhất, bền bỉ nhất trong thế giới Marvel.<br><br>Sản phẩm mô hình siêu anh hùng Spiderman 30cm có các đặc điểm nổi bật sau:<br><br>1. Chiều cao mô hình lý tưởng giúp bé dễ dàng quan sát và cầm nắm.<br><br>2. Mô hình siêu anh hùng được thiết kế tỉ mỉ, tinh xảo đến từng chi tiết, nhìn như nhân vật ngoài đời thực, mang đến cho bé những cảm giác thật nhất.<br><br>3. Sản phẩm làm từ chất liệu cao cấp, an toàn cho sức khỏe.<br><br>4. Màu sắc bắt mắt, nổi bật kích thích thị giác của trẻ em.<br><br>5. Nhân vật siêu anh hùng được trang bị các khớp chuyển động linh hoạt, có thể tạo ra nhiều tư thế vô cùng ngộ nghĩnh.<br><br>Bộ sản phẩm đồ chơi mô hình siêu anh hùng SPIDERMAN E7333 bao gồm:<br><br>01 mô hình người nhện<br>Vài nét về thương hiệu đồ chơi:<br><br>SPIDERMAN là một thương hiệu đồ chơi nổi tiếng của Hasbro xuất xứ từ Mỹ. Các sản phẩm của Spiderman được mô phỏng từ nhân vật người nhện của vũ trụ Marvel với nhiều mẫu mã đa dạng, phong phú. Đồng thời được sản xuất từ chất liệu cao cấp, đạt tiêu chuẩn Châu Âu, hứa hẹn sẽ mang đến cho trẻ em những trải nghiệm thú vị khi chơi cùng các nhân vật siêu anh hùng yêu thích.',1,9999,0),(34,'Chiến Binh Thú ZW47 BURNING LIGER Kèm Vũ Khí ZOIDS 3 153979','8481bb67e22eb5cb6fecb15865c5c064',749000,8600,3,1,'Đồ Chơi ZOIDS Chiến Binh Thú ZW47 Burning Liger Kèm Vũ Khí 153979<br>Mô tả sản phẩm<br><br>- Phù hợp cho trẻ từ 6 tuổi.<br><br>- Chất liệu nhựa và kim loại tạo độ cứng cáp cho sản phẩm.<br><br>- Thương hiệu Takara Tomy Nhật Bản, sản xuất tại Việt Nam.<br><br>ZOIDS ZW47 BURNING LIGER SET là sản phẩm đồ chơi dựa theo bộ phim hoạt hình ZOIDS 3 phát sóng trên YouTube Takaratomy. Sản phẩm đồ chơi được sản xuất theo công nghệ Nhật Bản: Tự tay lắp ráp, cho phép người dùng tự do sáng tạo, lắp ráp các bộ phận để tạo thanh thú máy hùng mạnh<br><br>Ngoài ra mô hình còn có thể di chuyển như trong phim. Bên trong sản phẩm có sách hướng dẫn đi kèm giúp việc lắp ráp dễ dàng.',1,8597,0),(35,'Mô Hình Optimus Prime Nguyên Bản 4.5 Inch TRANSFORMERS E0618','61594ea244e0d4e08d6180c465d2f040',249000,5900,3,1,'Chọn nhân vật Autobots hoặc Decepticons bạn yêu thích - khả năng chuyển đổi từ rô-bốt thành phương tiện chỉ trong vài bước lắp ráp',0,5900,0),(36,'Đồ Chơi Lắp Ráp Siêu xe McLaren F1 LEGO SPEED CHAMPIONS 76919 (245 chi tiết)','5165ebc47957f42d231c04465135f3f9',799000,13000,4,2,'Xe đua Thể thức 1 LEGO® Speed Champions Siêu xe McLaren F1 2023 dành cho các bé từ 9 tuổi trở lên, dành tặng cho những người hâm mộ cúp F1 và những người yêu thích sưu tầm các loại xe mang tính biểu tượng<br><br>• Siêu xe bao gồm một mô hình nhân vật minifigures tay đua với mũ bảo hiểm, tóc giả và cờ lê để bé có thể thực hiện các cuộc đua F1 dễ dàng hơn<br><br>• Mẫu Xe đua Siêu xe McLaren F1 2023 có màu sơn cam đen đặc trưng, cùng logo của nhà tài trợ, bánh xe có in hình Pirelli<br><br>• Bộ lắp ráp mang đến trải nghiệm chơi thú vị và là món quà lý tưởng cho trẻ từ 9 tuổi trở lên hoặc người sưu tập mô hình ô tô<br><br>• Kích thước – Chiếc ô tô LEGO® có thể lắp ráp gồm 245 mảnh này có chiều cao trên 1,5 inch (4 cm), dài 7 inch (19 cm) và rộng 2,5 inch (7 cm)',0,12999,20),(37,'Đồ Chơi Lắp Ráp Rồng Con Riyu LEGO NINJAGO 71810 (132 chi tiết)','8f2ed5266027e01cd879daf9b6697c51',449000,6700,3,2,'Đồ chơi lắp ráp Rồng con Riyu (71810) mang đến những pha hành động lấy cảm hứng từ phần 2 của bộ phim NINJAGO® Dragons Rising<br><br>Các chi tiết như Cánh, đuôi và chân của Rồng con Riyu có thể điểu chỉnh khiến chú rồng trở nên sinh động hơn<br><br>Bộ lắp ráp đi kèm với 3 nhân vật minifigures NINJAGO: Arin, được trang bị móc leo núi và phụ kiện kiếm katana, Sora với phụ kiện kiếm katana và Chiến binh mặt nạ sói hung ác với phụ kiện kiếm. Bộ lắp ráp có tất cả những gì cần thiết để giúp trẻ nhập vai trở thành một chiến binh ninja và tham gia các trận chiến gay cấn.<br><br>Bộ lắp ráp có 132 chi tiết',2,6698,0),(38,'Đồ chơi lắp ráp Phi thuyền liên hành tinh LEGO CITY 60430','7f7a223e8acd2cba5b0eb420736afe0c',599000,12000,3,2,'Sử dụng động cơ đầy uy lực, chuyển sang tốc độ ánh sáng và tiến vào hành trình đến những vùng không gian xa xôi trên tàu vũ trụ siêu thanh. Tiến vào bên trong chiếc máy bay phản lực mạnh mẽ để thực hiện những chuyến đi táo bạo trong không gian và khám phá hành tinh. Tận hưởng những cuộc phiêu lưu giữa các thiên hà vô tận với phi hành đoàn không gian của Thành phố LEGO® City!<br><br>• Đồ chơi lắp ráp Phi thuyền liên hành tinh – Bé yêu với niềm đam mê không gian có thể bắt đầu hành trình giữa các thiên hà với bộ lắp ráp tàu không gian thú vị này.<br><br>• Có gì trong hộp nào? – bộ trò chơi này bao gồm mọi thứ bé cần để chế tạo tàu vũ trụ giữa du hành các vì sao và mô hình minifigure của phi hành đoàn không gian<br><br>• Trò chơi sáng tạo – Bé có thể kích hoạt bộ động cơ chính có thể gập lại của tàu vũ trụ để du hành vũ trụ nhanh như chớp.<br><br>• Món quà tuyệt vời cho bé yêu – Bộ trò chơi này chắc chắn sẽ là một món quà thú vị dành cho những bé yêu thích những chuyến phiêu lưu mạo hiểm ngoài vũ trụ, hoặc yêu thích tàu du dành, máy bay và các phương tiện khác.<br><br>• Biến mọi thứ trở nên thú vị – Bộ trò chơi xây dựng LEGO® City giúp trẻ phát triển sự tự tin và các kỹ năng sống quan trọng thông qua trò chơi và thể hiện sự sáng tạo không giới hạn<br><br>• Kích thước – Bộ lắp ráp tàu không gian này gồm có 240 mảnh, sau khi hoàn thiện có chiều cao trên 1,5 inch (4 cm), dài 8,5 inch (22 cm) và rộng 6,5 inch (17 cm).',1,12000,10),(39,'Bearbrick atmos x WIND AND SEA Set BB AWAS','92e16b274c517858c35a040728568373',4790000,2000,4,7,'Be@rbrick là gì đôi khi lại là câu hỏi đầu tiên của một tín đồ Be@rbrick tiềm năng. Được chế tác bởi Medicom Toy của Nhật Bản, về cơ bản những chú gấu Bearbrick xuất hiện rất đơn giản ở những cái nhìn đầu tiên, một bức tượng hình gấu bằng nhựa với nhiều kích cỡ và màu sắc khác nhau.<br><br>Tuy nhiên, món đồ chơi này đã được đưa vào các phòng trưng bày nghệ thuật, được yêu quý bởi Pharrell Williams, Fabo Nguyễn, Huyền My, Văn Toàn, Grace Coddington,… Sẽ không quá lời khi nói những chú gấu đồ chơi bằng nhựa vinyl này đã trở thành thứ món đồ hypebeast thể hiện sự hiện đại, đóng vai trò quan trọng trong sự giao thoa giữa phong cách, nghệ thuật và thời trang.<br><br>BE @ RBRICKS được thiết kế và sản xuất bởi Medicom Toy của Nhật Bản, một công ty nổi tiếng với những bức tượng nhỏ bằng nhựa. Công ty được thành lập vào năm 1996 để sản xuất các phiên bản giới hạn và các sản phẩm được cấp phép. Qua nhiều năm, Medicom Toy đã tạo ra những bức tượng nhỏ bằng nhựa của văn hóa đại chúng.<br><br>Thiết kế và ý tưởng của Bearbrick dựa trên một dòng sản phẩm khác của Medicom Toy – Kubrick , để tỏ lòng kính trọng với đạo diễn lừng danh Stanley Kubrick . Dòng Kubricks cũng được thể hiện bằng một logo sử dụng phông chữ giống như áp phích chính thức của A Clockwork Orange , trong khi tên cũng trùng hợp bao gồm từ tiếng Nhật có nghĩa là chín – “ku”. Cả Kubricks và BE @ RBRICKS đều bao gồm chín phần – đầu, thân, hông, cánh tay, bàn tay và chân với các khớp có thể cử động. Trong khi đồ chơi Kubrick mang hình dáng giống con người, BE @ RBRICK, như đã đề cập, là một chú gấu được nhân hóa.<br><br>Bearbrick atmos x WIND AND SEA 100% & 400% Set hiện đã có sẵn tại Sneaker Daily với mức giá rất ưu đãi dành cho các tín đồ của bộ môn này.',0,1998,0),(42,'Bearbrick Death Trooper Black  BB-DTB','e8d84cd662c6517866be83408452c574',8090000,4000,4,7,'Be@rbrick là gì đôi khi lại là câu hỏi đầu tiên của một tín đồ Be@rbrick tiềm năng. Được chế tác bởi Medicom Toy của Nhật Bản, về cơ bản những chú gấu Bearbrick xuất hiện rất đơn giản ở những cái nhìn đầu tiên, một bức tượng hình gấu bằng nhựa với nhiều kích cỡ và màu sắc khác nhau.<br><br>Tuy nhiên, món đồ chơi này đã được đưa vào cá